package com.example.bank_account_management_api.service;

import com.example.bank_account_management_api.entity.BankAccount;
import com.example.bank_account_management_api.repository.BankAccountRepository;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import jakarta.persistence.UniqueConstraint;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class BankAccountServiceTest {

    @Mock
    private BankAccountRepository repository;

    @InjectMocks
    private BankAccountService service;

    @Test
    void testCreateSetsDefaults() {
        BankAccount account = BankAccount.builder()
                .accountNumber("ACC123")
                .accountHolderName("John Doe")
                .balance(null)
                .build();

        when(repository.save(any(BankAccount.class))).thenAnswer(invocation -> invocation.getArgument(0));

        BankAccount created = service.create(account);

        assertNotNull(created.getCreatedAt(), "createdAt should be set");
        assertNotNull(created.getUpdatedAt(), "updatedAt should be set");
        assertEquals(BigDecimal.ZERO, created.getBalance(), "balance should default to zero");
        verify(repository).save(created);
    }

    @Test
    void testFindAllReturnsList() {
        BankAccount acc1 = BankAccount.builder().id(1L).accountNumber("A1").accountHolderName("Alice")
                .balance(BigDecimal.valueOf(100)).build();
        BankAccount acc2 = BankAccount.builder().id(2L).accountNumber("A2").accountHolderName("Bob")
                .balance(BigDecimal.valueOf(200)).build();

        when(repository.findAll()).thenReturn(Arrays.asList(acc1, acc2));

        List<BankAccount> result = service.findAll();

        assertEquals(2, result.size());
        assertTrue(result.containsAll(Arrays.asList(acc1, acc2)));
        verify(repository).findAll();
    }

    @Test
    void testFindByIdSuccess() {
        BankAccount acc = BankAccount.builder().id(10L).accountNumber("A10").accountHolderName("Charlie")
                .balance(BigDecimal.valueOf(500)).build();

        when(repository.findById(10L)).thenReturn(Optional.of(acc));

        BankAccount found = service.findById(10L);

        assertEquals(acc, found);
        verify(repository).findById(10L);
    }

    @Test
    void testFindByIdNotFound() {
        when(repository.findById(99L)).thenReturn(Optional.empty());

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> service.findById(99L));

        assertEquals("BankAccount not found with id 99", ex.getMessage());
        verify(repository).findById(99L);
    }

    @Test
    void testUpdateSuccess() {
        BankAccount existing = BankAccount.builder()
                .id(5L)
                .accountNumber("OLD123")
                .accountHolderName("Old Name")
                .balance(BigDecimal.valueOf(1000))
                .createdAt(LocalDateTime.now().minusDays(1))
                .updatedAt(LocalDateTime.now().minusDays(1))
                .build();

        BankAccount updatedInfo = BankAccount.builder()
                .accountNumber("NEW123")
                .accountHolderName("New Name")
                .balance(BigDecimal.valueOf(1500))
                .build();

        when(repository.findById(5L)).thenReturn(Optional.of(existing));
        when(repository.save(any(BankAccount.class))).thenAnswer(invocation -> invocation.getArgument(0));

        BankAccount result = service.update(5L, updatedInfo);

        assertEquals("NEW123", result.getAccountNumber());
        assertEquals("New Name", result.getAccountHolderName());
        assertEquals(BigDecimal.valueOf(1500), result.getBalance());
        assertNotNull(result.getUpdatedAt());
        verify(repository).findById(5L);
        verify(repository).save(existing);
    }

    @Test
    void testDeleteCallsRepository() {
        doNothing().when(repository).deleteById(7L);

        service.delete(7L);

        verify(repository, times(1)).deleteById(7L);
    }

    @Test
    void testDepositSuccess() {
        BankAccount acc = BankAccount.builder()
                .id(3L)
                .balance(BigDecimal.valueOf(200))
                .build();

        when(repository.findById(3L)).thenReturn(Optional.of(acc));
        when(repository.save(any(BankAccount.class))).thenAnswer(invocation -> invocation.getArgument(0));

        BankAccount result = service.deposit(3L, BigDecimal.valueOf(50));

        assertEquals(BigDecimal.valueOf(250), result.getBalance());
        assertNotNull(result.getUpdatedAt());
        verify(repository).findById(3L);
        verify(repository).save(acc);
    }

    @Test
    void testDepositInvalidAmount() {
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> service.deposit(1L, BigDecimal.ZERO));

        assertEquals("Deposit amount must be positive", ex.getMessage());
    }

    @Test
    void testWithdrawSuccess() {
        BankAccount acc = BankAccount.builder()
                .id(4L)
                .balance(BigDecimal.valueOf(500))
                .build();

        when(repository.findById(4L)).thenReturn(Optional.of(acc));
        when(repository.save(any(BankAccount.class))).thenAnswer(invocation -> invocation.getArgument(0));

        BankAccount result = service.withdraw(4L, BigDecimal.valueOf(200));

        assertEquals(BigDecimal.valueOf(300), result.getBalance());
        assertNotNull(result.getUpdatedAt());
        verify(repository).findById(4L);
        verify(repository).save(acc);
    }

    @Test
    void testWithdrawInsufficientFunds() {
        BankAccount acc = BankAccount.builder()
                .id(8L)
                .balance(BigDecimal.valueOf(100))
                .build();

        when(repository.findById(8L)).thenReturn(Optional.of(acc));

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> service.withdraw(8L, BigDecimal.valueOf(150)));

        assertEquals("Insufficient funds for withdrawal", ex.getMessage());
        verify(repository).findById(8L);
    }

    @Test
    void testWithdrawInvalidAmount() {
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> service.withdraw(2L, BigDecimal.valueOf(-10)));

        assertEquals("Withdraw amount must be positive", ex.getMessage());
    }
}

package com.example.patient_appointment_management_api.service;

import com.example.patient_appointment_management_api.entity.Appointment;
import com.example.patient_appointment_management_api.entity.AppointmentStatus;
import com.example.patient_appointment_management_api.repository.AppointmentRepository;
import jakarta.persistence.Entity;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @InjectMocks
    private AppointmentService appointmentService;

    @Test
    void create_ShouldSetDefaultStatusWhenNullAndSave() {
        Appointment input = new Appointment(null,
                "John Doe",
                "Dr. Smith",
                LocalDateTime.now(),
                "Routine check",
                null);

        when(appointmentRepository.save(any(Appointment.class))).thenAnswer(invocation -> {
            Appointment a = invocation.getArgument(0);
            a.setId(1L);
            return a;
        });

        Appointment result = appointmentService.create(input);

        assertNotNull(result.getId());
        assertEquals(AppointmentStatus.SCHEDULED, result.getStatus());

        ArgumentCaptor<Appointment> captor = ArgumentCaptor.forClass(Appointment.class);
        verify(appointmentRepository).save(captor.capture());
        Appointment saved = captor.getValue();
        assertEquals(AppointmentStatus.SCHEDULED, saved.getStatus());
    }

    @Test
    void create_ShouldPreserveProvidedStatus() {
        Appointment input = new Appointment(null,
                "Jane Doe",
                "Dr. Adams",
                LocalDateTime.now(),
                "Consultation",
                AppointmentStatus.CONFIRMED);

        when(appointmentRepository.save(any(Appointment.class))).thenAnswer(invocation -> {
            Appointment a = invocation.getArgument(0);
            a.setId(2L);
            return a;
        });

        Appointment result = appointmentService.create(input);

        assertEquals(AppointmentStatus.CONFIRMED, result.getStatus());
        verify(appointmentRepository).save(any(Appointment.class));
    }

    @Test
    void getById_ShouldReturnAppointmentWhenFound() {
        Appointment stored = new Appointment(3L,
                "Alice",
                "Dr. Brown",
                LocalDateTime.now(),
                "Follow‑up",
                AppointmentStatus.SCHEDULED);

        when(appointmentRepository.findById(3L)).thenReturn(Optional.of(stored));

        Appointment result = appointmentService.getById(3L);

        assertSame(stored, result);
        verify(appointmentRepository).findById(3L);
    }

    @Test
    void getById_ShouldThrowWhenNotFound() {
        when(appointmentRepository.findById(99L)).thenReturn(Optional.empty());

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> appointmentService.getById(99L));

        assertTrue(ex.getMessage().contains("Appointment not found with id: 99"));
        verify(appointmentRepository).findById(99L);
    }

    @Test
    void update_ShouldModifyExistingAppointment() {
        Appointment existing = new Appointment(4L,
                "Bob",
                "Dr. Green",
                LocalDateTime.of(2024, 5, 20, 10, 0),
                "Initial reason",
                AppointmentStatus.SCHEDULED);

        Appointment updatedInfo = new Appointment(null,
                "Bob Updated",
                "Dr. Green Updated",
                LocalDateTime.of(2024, 5, 21, 11, 30),
                "Updated reason",
                null); // status left null should stay unchanged

        when(appointmentRepository.findById(4L)).thenReturn(Optional.of(existing));

        Appointment result = appointmentService.update(4L, updatedInfo);

        assertEquals(4L, result.getId());
        assertEquals("Bob Updated", result.getPatientName());
        assertEquals("Dr. Green Updated", result.getDoctorName());
        assertEquals(LocalDateTime.of(2024, 5, 21, 11, 30), result.getAppointmentDate());
        assertEquals("Updated reason", result.getReason());
        assertEquals(AppointmentStatus.SCHEDULED, result.getStatus()); // unchanged

        verify(appointmentRepository).findById(4L);
        verifyNoMoreInteractions(appointmentRepository);
    }

    @Test
    void delete_ShouldRemoveAppointmentWhenExists() {
        when(appointmentRepository.existsById(5L)).thenReturn(true);
        doNothing().when(appointmentRepository).deleteById(5L);

        assertDoesNotThrow(() -> appointmentService.delete(5L));

        verify(appointmentRepository).existsById(5L);
        verify(appointmentRepository).deleteById(5L);
    }

    @Test
    void confirm_ShouldSetStatusToConfirmed() {
        Appointment existing = new Appointment(6L,
                "Charlie",
                "Dr. White",
                LocalDateTime.now(),
                "Consult",
                AppointmentStatus.SCHEDULED);

        when(appointmentRepository.findById(6L)).thenReturn(Optional.of(existing));

        Appointment result = appointmentService.confirm(6L);

        assertEquals(AppointmentStatus.CONFIRMED, result.getStatus());
        verify(appointmentRepository).findById(6L);
    }

    @Test
    void cancel_ShouldSetStatusToCanceled() {
        Appointment existing = new Appointment(7L,
                "Diana",
                "Dr. Black",
                LocalDateTime.now(),
                "Therapy",
                AppointmentStatus.SCHEDULED);

        when(appointmentRepository.findById(7L)).thenReturn(Optional.of(existing));

        Appointment result = appointmentService.cancel(7L);

        assertEquals(AppointmentStatus.CANCELED, result.getStatus());
        verify(appointmentRepository).findById(7L);
    }
}

package com.example.parking_lot_management_system_api.service;

import com.example.parking_lot_management_system_api.entity.ParkingTicket;
import com.example.parking_lot_management_system_api.exception.ResourceNotFoundException;
import com.example.parking_lot_management_system_api.repository.ParkingTicketRepository;
import jakarta.persistence.Entity;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class ParkingTicketServiceTest {

    @Mock
    private ParkingTicketRepository ticketRepository;

    @InjectMocks
    private ParkingTicketService service;

    @Test
    void createTicket_setsActiveAndEntryTime_andSaves() {
        ParkingTicket input = new ParkingTicket();
        input.setVehicleNumber("ABC-123");
        input.setSlotNumber(10);

        when(ticketRepository.save(any(ParkingTicket.class))).thenAnswer(invocation -> invocation.getArgument(0));

        ParkingTicket result = service.createTicket(input);

        assertTrue(result.getIsActive(), "Ticket should be active after creation");
        assertNotNull(result.getEntryTime(), "Entry time should be set");
        assertEquals("ABC-123", result.getVehicleNumber());
        assertEquals(10, result.getSlotNumber());

        ArgumentCaptor<ParkingTicket> captor = ArgumentCaptor.forClass(ParkingTicket.class);
        verify(ticketRepository).save(captor.capture());
        ParkingTicket saved = captor.getValue();
        assertSame(result, saved, "Returned ticket should be the same instance saved");
    }

    @Test
    void getTicketById_returnsTicket_whenExists() {
        ParkingTicket ticket = new ParkingTicket();
        ticket.setId(1L);
        ticket.setVehicleNumber("XYZ-999");
        when(ticketRepository.findById(1L)).thenReturn(Optional.of(ticket));

        ParkingTicket found = service.getTicketById(1L);

        assertEquals(ticket, found);
        verify(ticketRepository).findById(1L);
    }

    @Test
    void getTicketById_throwsResourceNotFound_whenMissing() {
        when(ticketRepository.findById(42L)).thenReturn(Optional.empty());

        ResourceNotFoundException ex = assertThrows(ResourceNotFoundException.class,
                () -> service.getTicketById(42L));

        assertTrue(ex.getMessage().contains("ParkingTicket not found with id 42"));
        verify(ticketRepository).findById(42L);
    }

    @Test
    void updateTicket_updatesFields_andSaves() {
        ParkingTicket existing = new ParkingTicket();
        existing.setId(5L);
        existing.setVehicleNumber("OLD-001");
        existing.setSlotNumber(1);
        existing.setIsActive(true);
        existing.setEntryTime(LocalDateTime.now().minusHours(2));

        ParkingTicket updated = new ParkingTicket();
        updated.setVehicleNumber("NEW-002");
        updated.setSlotNumber(2);
        updated.setIsActive(false);
        // leave entryTime, exitTime, totalFee null to test conditional updates

        when(ticketRepository.findById(5L)).thenReturn(Optional.of(existing));
        when(ticketRepository.save(any(ParkingTicket.class))).thenAnswer(invocation -> invocation.getArgument(0));

        ParkingTicket result = service.updateTicket(5L, updated);

        assertEquals("NEW-002", result.getVehicleNumber());
        assertEquals(2, result.getSlotNumber());
        assertFalse(result.getIsActive());
        // entryTime should remain unchanged
        assertNotNull(result.getEntryTime());
        verify(ticketRepository).findById(5L);
        verify(ticketRepository).save(existing);
    }

    @Test
    void deleteTicket_deletesWhenExists() {
        ParkingTicket ticket = new ParkingTicket();
        ticket.setId(7L);
        when(ticketRepository.findById(7L)).thenReturn(Optional.of(ticket));
        doNothing().when(ticketRepository).delete(ticket);

        service.deleteTicket(7L);

        verify(ticketRepository).findById(7L);
        verify(ticketRepository).delete(ticket);
    }

    @Test
    void processExit_calculatesFeeAndDeactivatesTicket() {
        ParkingTicket ticket = new ParkingTicket();
        ticket.setId(3L);
        ticket.setIsActive(true);
        ticket.setEntryTime(LocalDateTime.now().minusMinutes(30));

        when(ticketRepository.findById(3L)).thenReturn(Optional.of(ticket));
        when(ticketRepository.save(any(ParkingTicket.class))).thenAnswer(invocation -> invocation.getArgument(0));

        ParkingTicket result = service.processExit(3L);

        assertNotNull(result.getExitTime(), "Exit time should be set");
        assertEquals(new BigDecimal("5.00"), result.getTotalFee(), "Fee should be 1 hour * $5.00");
        assertFalse(result.getIsActive(), "Ticket should be inactive after exit");
        verify(ticketRepository).findById(3L);
        verify(ticketRepository).save(ticket);
    }

    @Test
    void processExit_throwsIllegalStateWhenAlreadyExited() {
        ParkingTicket ticket = new ParkingTicket();
        ticket.setId(4L);
        ticket.setIsActive(false);
        when(ticketRepository.findById(4L)).thenReturn(Optional.of(ticket));

        IllegalStateException ex = assertThrows(IllegalStateException.class,
                () -> service.processExit(4L));

        assertEquals("Ticket is already processed for exit.", ex.getMessage());
        verify(ticketRepository).findById(4L);
        verify(ticketRepository, never()).save(any());
    }

    @Test
    void getActiveTickets_returnsRepositoryResult() {
        ParkingTicket active1 = new ParkingTicket();
        ParkingTicket active2 = new ParkingTicket();
        List<ParkingTicket> activeList = Arrays.asList(active1, active2);
        when(ticketRepository.findByIsActiveTrue()).thenReturn(activeList);

        List<ParkingTicket> result = service.getActiveTickets();

        assertSame(activeList, result);
        verify(ticketRepository).findByIsActiveTrue();
    }
}

package com.example.course_registration_api.service;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

import com.example.course_registration_api.entity.Course;
import com.example.course_registration_api.repository.CourseRepository;
import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

@ExtendWith(MockitoExtension.class)
class CourseServiceTest {

    @Mock
    private CourseRepository repository;

    @Mock
    private EntityManager entityManager;

    @InjectMocks
    private CourseService service;

    @Test
    @DisplayName("getAllCourses returns all courses from repository")
    void testGetAllCourses() {
        Course c1 = new Course(1L, "Math", "Algebra", 30, 5);
        Course c2 = new Course(2L, "Physics", "Mechanics", 25, 10);
        List<Course> expected = Arrays.asList(c1, c2);

        when(repository.findAll()).thenReturn(expected);

        List<Course> result = service.getAllCourses();

        assertEquals(expected, result);
        verify(repository).findAll();
    }

    @Nested
    @DisplayName("getCourseById")
    class GetCourseById {

        @Test
        @DisplayName("returns course when found")
        void whenFound() {
            Course course = new Course(1L, "Math", "Algebra", 30, 5);
            when(repository.findById(1L)).thenReturn(Optional.of(course));

            Course result = service.getCourseById(1L);

            assertEquals(course, result);
            verify(repository).findById(1L);
        }

        @Test
        @DisplayName("throws ResponseStatusException with NOT_FOUND when missing")
        void whenNotFound() {
            when(repository.findById(99L)).thenReturn(Optional.empty());

            ResponseStatusException ex = assertThrows(ResponseStatusException.class,
                    () -> service.getCourseById(99L));

            assertEquals(HttpStatus.NOT_FOUND, ex.getStatusCode());
            assertEquals("Course not found", ex.getReason());
            verify(repository).findById(99L);
        }
    }

    @Test
    @DisplayName("createCourse sets enrolledCount to 0 and saves")
    void testCreateCourse() {
        Course input = new Course(null, "Chemistry", "Organic", 20, null);
        Course toSave = new Course(null, "Chemistry", "Organic", 20, 0);
        Course saved = new Course(3L, "Chemistry", "Organic", 20, 0);

        when(repository.save(any(Course.class))).thenReturn(saved);

        Course result = service.createCourse(input);

        // enrolledCount should be set to 0 before saving
        assertEquals(0, input.getEnrolledCount());
        assertEquals(saved, result);
        verify(repository).save(input);
    }

    @Nested
    @DisplayName("updateCourse")
    class UpdateCourse {

        @Test
        @DisplayName("updates mutable fields and preserves enrolledCount")
        void whenFound() {
            Course existing = new Course(1L, "Old", "Desc", 10, 3);
            Course updatedInfo = new Course(null, "New", "New Desc", 15, 99); // enrolledCount should be ignored

            when(repository.findById(1L)).thenReturn(Optional.of(existing));
            when(repository.save(any(Course.class))).thenAnswer(invocation -> invocation.getArgument(0));

            Course result = service.updateCourse(1L, updatedInfo);

            assertEquals("New", result.getName());
            assertEquals("New Desc", result.getDescription());
            assertEquals(15, result.getMaxCapacity());
            assertEquals(3, result.getEnrolledCount()); // unchanged
            verify(repository).findById(1L);
            verify(repository).save(existing);
        }

        @Test
        @DisplayName("throws ResponseStatusException when course does not exist")
        void whenNotFound() {
            Course updatedInfo = new Course(null, "New", "Desc", 15, 0);
            when(repository.findById(5L)).thenReturn(Optional.empty());

            ResponseStatusException ex = assertThrows(ResponseStatusException.class,
                    () -> service.updateCourse(5L, updatedInfo));

            assertEquals(HttpStatus.NOT_FOUND, ex.getStatusCode());
            assertEquals("Course not found", ex.getReason());
            verify(repository).findById(5L);
        }
    }

    @Nested
    @DisplayName("deleteCourse")
    class DeleteCourse {

        @Test
        @DisplayName("deletes existing course")
        void whenExists() {
            when(repository.existsById(2L)).thenReturn(true);
            doNothing().when(repository).deleteById(2L);

            assertDoesNotThrow(() -> service.deleteCourse(2L));

            verify(repository).existsById(2L);
            verify(repository).deleteById(2L);
        }

        @Test
        @DisplayName("throws ResponseStatusException when course not found")
        void whenNotExists() {
            when(repository.existsById(99L)).thenReturn(false);

            ResponseStatusException ex = assertThrows(ResponseStatusException.class,
                    () -> service.deleteCourse(99L));

            assertEquals(HttpStatus.NOT_FOUND, ex.getStatusCode());
            assertEquals("Course not found", ex.getReason());
            verify(repository).existsById(99L);
            verify(repository, never()).deleteById(anyLong());
        }
    }

    @Nested
    @DisplayName("enrollStudent")
    class EnrollStudent {

        @Test
        @DisplayName("enrolls student when capacity allows")
        void whenCapacityAvailable() {
            Course course = new Course(1L, "Biology", "Genetics", 5, 2);
            Course afterSave = new Course(1L, "Biology", "Genetics", 5, 3);

            when(repository.findById(1L)).thenReturn(Optional.of(course));
            doNothing().when(entityManager).lock(course, LockModeType.PESSIMISTIC_WRITE);
            when(repository.save(course)).thenReturn(afterSave);

            Course result = service.enrollStudent(1L);

            assertEquals(3, result.getEnrolledCount());
            verify(repository).findById(1L);
            verify(entityManager).lock(course, LockModeType.PESSIMISTIC_WRITE);
            verify(repository).save(course);
        }

        @Test
        @DisplayName("throws IllegalStateException when course is full")
        void whenCourseFull() {
            Course fullCourse = new Course(2L, "History", "World", 10, 10);

            when(repository.findById(2L)).thenReturn(Optional.of(fullCourse));
            doNothing().when(entityManager).lock(fullCourse, LockModeType.PESSIMISTIC_WRITE);

            IllegalStateException ex = assertThrows(IllegalStateException.class,
                    () -> service.enrollStudent(2L));

            assertEquals("Course is full", ex.getMessage());
            verify(repository).findById(2L);
            verify(entityManager).lock(fullCourse, LockModeType.PESSIMISTIC_WRITE);
            verify(repository, never()).save(any());
        }

        @Test
        @DisplayName("throws ResponseStatusException when course not found")
        void whenNotFound() {
            when(repository.findById(99L)).thenReturn(Optional.empty());

            ResponseStatusException ex = assertThrows(ResponseStatusException.class,
                    () -> service.enrollStudent(99L));

            assertEquals(HttpStatus.NOT_FOUND, ex.getStatusCode());
            assertEquals("Course not found", ex.getReason());
            verify(repository).findById(99L);
            verify(entityManager, never()).lock(any(), any());
            verify(repository, never()).save(any());
        }
    }
}

package com.example.gym_membership_system_api.service;

