    private MemberRepository memberRepository;

    @InjectMocks
    private MemberService memberService;

    private PlanType anyPlan() {
        // obtain any existing enum constant without depending on its name
        return PlanType.values()[0];
    }

    @Test
    void createMember_success() {
        // given
        Member input = new Member(null, "John Doe", "john@example.com", anyPlan(),
                LocalDate.now(), LocalDate.now().plusMonths(1), null);
        Member saved = new Member(1L, "John Doe", "john@example.com", anyPlan(),
                input.getStartDate(), input.getEndDate(), true);

        when(memberRepository.save(any(Member.class))).thenReturn(saved);

        // when
        Member result = memberService.create(input);

        // then
        assertNotNull(result);
        assertEquals(1L, result.getId());
        assertTrue(result.getIsActive());

        ArgumentCaptor<Member> captor = ArgumentCaptor.forClass(Member.class);
        verify(memberRepository).save(captor.capture());
        Member captured = captor.getValue();
        assertTrue(captured.getIsActive());
    }

    @Test
    void createMember_validation_missingName() {
        Member input = new Member(null, "", "john@example.com", anyPlan(),
                LocalDate.now(), LocalDate.now().plusMonths(1), null);

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> memberService.create(input));
        assertEquals("Member name is required", ex.getMessage());
        verifyNoInteractions(memberRepository);
    }

    @Test
    void findById_success() {
        Member member = new Member(1L, "Jane", "jane@example.com", anyPlan(),
                LocalDate.now(), LocalDate.now().plusMonths(1), true);
        when(memberRepository.findById(1L)).thenReturn(Optional.of(member));

        Member result = memberService.findById(1L);

        assertNotNull(result);
        assertEquals("Jane", result.getName());
        verify(memberRepository).findById(1L);
    }

    @Test
    void findById_notFound() {
        when(memberRepository.findById(99L)).thenReturn(Optional.empty());

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> memberService.findById(99L));
        assertEquals("Member not found with id: 99", ex.getMessage());
        verify(memberRepository).findById(99L);
    }

    @Test
    void updateMember_success() {
        Member existing = new Member(1L, "Old Name", "old@example.com", anyPlan(),
                LocalDate.now().minusMonths(2), LocalDate.now().plusMonths(1), true);
        Member updated = new Member(null, "New Name", "new@example.com", anyPlan(),
                LocalDate.now().minusMonths(1), LocalDate.now().plusMonths(2), false);
        Member saved = new Member(1L, "New Name", "new@example.com", anyPlan(),
                updated.getStartDate(), updated.getEndDate(), false);

        when(memberRepository.findById(1L)).thenReturn(Optional.of(existing));
        when(memberRepository.save(any(Member.class))).thenReturn(saved);

        Member result = memberService.update(1L, updated);

        assertNotNull(result);
        assertEquals("New Name", result.getName());
        assertEquals("new@example.com", result.getEmail());
        assertEquals(updated.getStartDate(), result.getStartDate());
        assertEquals(updated.getEndDate(), result.getEndDate());
        assertFalse(result.getIsActive());

        ArgumentCaptor<Member> captor = ArgumentCaptor.forClass(Member.class);
        verify(memberRepository).save(captor.capture());
        Member captured = captor.getValue();
        assertEquals(1L, captured.getId());
        assertEquals("New Name", captured.getName());
    }

    @Test
    void updateMember_notFound() {
        Member updated = new Member(null, "New Name", "new@example.com", anyPlan(),
                LocalDate.now(), LocalDate.now().plusMonths(1), true);
        when(memberRepository.findById(5L)).thenReturn(Optional.empty());

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> memberService.update(5L, updated));
        assertEquals("Member not found with id: 5", ex.getMessage());
        verify(memberRepository).findById(5L);
        verify(memberRepository, never()).save(any());
    }

    @Test
    void deleteMember_success() {
        Member existing = new Member(2L, "To Delete", "del@example.com", anyPlan(),
                LocalDate.now(), LocalDate.now().plusMonths(1), true);
        when(memberRepository.findById(2L)).thenReturn(Optional.of(existing));
        doNothing().when(memberRepository).delete(existing);

        assertDoesNotThrow(() -> memberService.delete(2L));

        verify(memberRepository).findById(2L);
        verify(memberRepository).delete(existing);
    }

    @Test
    void deleteMember_notFound() {
        when(memberRepository.findById(3L)).thenReturn(Optional.empty());

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> memberService.delete(3L));
        assertEquals("Member not found with id: 3", ex.getMessage());

        verify(memberRepository).findById(3L);
        verify(memberRepository, never()).delete(any());
    }

    @Test
    void renewMember_success() {
        LocalDate currentEnd = LocalDate.of(2023, 12, 31);
        Member existing = new Member(10L, "Renewable", "renew@example.com", anyPlan(),
                LocalDate.of(2023, 1, 1), currentEnd, true);
        Member saved = new Member(10L, "Renewable", "renew@example.com", anyPlan(),
                existing.getStartDate(), currentEnd.plusMonths(1), true);

        when(memberRepository.findById(10L)).thenReturn(Optional.of(existing));
        when(memberRepository.save(any(Member.class))).thenReturn(saved);

        Member result = memberService.renew(10L);

        assertNotNull(result);
        assertEquals(currentEnd.plusMonths(1), result.getEndDate());

        ArgumentCaptor<Member> captor = ArgumentCaptor.forClass(Member.class);
        verify(memberRepository).save(captor.capture());
        Member captured = captor.getValue();
        assertEquals(currentEnd.plusMonths(1), captured.getEndDate());
        assertTrue(captured.getIsActive());
    }

    @Test
    void renewMember_notFound() {
        when(memberRepository.findById(99L)).thenReturn(Optional.empty());

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> memberService.renew(99L));
        assertEquals("Member not found with id: 99", ex.getMessage());

        verify(memberRepository).findById(99L);
        verify(memberRepository, never()).save(any());
    }
